{
  "name": "kessoku-ultimate-bocchi",
  "version": "1.0.0",
  "description": "Kessoku Ultimate Bocchi Theme: a Bocchi the Rock!-inspired charcoal-and-pink skin for all of Claude Code (an engine theme plus every render site), a live Kessoku Band panel with the band on stage as animated pixel-art sprites under spotlights and their subagents as songs on a setlist (solo any member) and band subagent types Claude can delegate to by name, and themed Cache Tax, Blast Radius, Filetree, Reflect and Replay Theater gags.",
  "author": {
    "name": "Dylan"
  },
  "types": "./types/index.d.ts",
  "userConfig": {
    "applyTheme": {
      "type": "boolean",
      "title": "Kessoku engine theme",
      "description": "Offer to switch Claude Code's theme to the Kessoku Bocchi theme (prompt border, diffs, status colors, everything the engine draws); /bocchi theme on|off changes it later",
      "default": true
    },
    "transcriptSkin": {
      "type": "string",
      "title": "Transcript skin",
      "description": "How much of the transcript the band restyles: full (messages, tool groups, turn footer, hint line, question dialog), light (only the small lines: footer, hint, notices), or none",
      "options": [
        "full",
        "light",
        "none"
      ],
      "default": "full"
    },
    "characterArt": {
      "type": "string",
      "title": "Character art",
      "description": "How the band is drawn: sprites (animated pixel art, rendered with Remotion: the live-house stage and animated pictures in the desktop app, block-character pixels in a terminal) or kaomoji (the text faces, and the panel's text layout). Text-only spots (status line, toasts) keep the kaomoji either way",
      "options": [
        "sprites",
        "kaomoji"
      ],
      "default": "sprites"
    },
    "restyleOthers": {
      "type": "boolean",
      "title": "Restyle other mods",
      "description": "Give other mods' panels pink borders and theme text where they left colors unset (a ui.resolve hook; off leaves their looks alone)",
      "default": false
    },
    "toasts": {
      "type": "string",
      "title": "Toasts",
      "description": "Which band toasts to show: all (every subagent on and off stage), important (the guard, commits, the theme, a cold cache), or none. The native notifications (the guard holding a command, a long set done, the cache about to go cold) follow it: silent under none",
      "options": [
        "all",
        "important",
        "none"
      ],
      "default": "all"
    },
    "accent": {
      "type": "string",
      "title": "Accent color",
      "description": "Accent for borders and highlights: a theme key such as claude (follows the active theme), a hex color, or a terminal color name",
      "default": "claude"
    },
    "paintBackgrounds": {
      "type": "boolean",
      "title": "Charcoal backgrounds",
      "description": "Paint dark charcoal backgrounds behind the theme's own panels and cards (skipped automatically on a light theme)",
      "default": true
    },
    "toolCards": {
      "type": "string",
      "title": "Tool row cards",
      "description": "Which tool rows get a stylized pink border: every tool call, only file edits, or none",
      "options": [
        "all",
        "edits",
        "none"
      ],
      "default": "all"
    },
    "spinnerWords": {
      "type": "boolean",
      "title": "Band spinner words",
      "description": "Swap the spinner's verb for band-themed ones that follow what the turn is doing (terminal only)",
      "default": true
    },
    "cacheTtlMinutes": {
      "type": "number",
      "title": "Cache TTL (minutes)",
      "description": "Prompt-cache lifetime Cache Tax assumes when the engine has not said: 60 for a subscription session, 5 for a plain API key",
      "default": 60
    },
    "keepWarmMinutes": {
      "type": "number",
      "title": "Keepwarm default (minutes)",
      "description": "How long /keepwarm keeps the cache warm when given no duration",
      "default": 360
    },
    "reflect": {
      "type": "boolean",
      "title": "Reflect memos",
      "description": "Let Nijika turn your corrections into CLAUDE.md rules (one tiny Haiku call per correction), and let Claude propose one itself through the memo tool; you press Save either way",
      "default": true
    },
    "openPanelOnStart": {
      "type": "boolean",
      "title": "Panel on start",
      "description": "Open the Kessoku Band panel when the session starts, where the terminal is wide enough for a sidebar",
      "default": true
    },
    "autoSolo": {
      "type": "boolean",
      "title": "Auto solo",
      "description": "When a member takes a new subagent, open her channel across the panel's mixer (her solo) for ten seconds, then return to the mix; a solo you chose yourself is never cut short",
      "default": false
    }
  }
}

files.types/index.d.ts:
// Kessoku Ultimate Bocchi Theme: the state contract.
//
// Every value the mod keeps in `$.state` (the session's own, so it survives a
// hot reload of the module) is declared here under the mod's name. The hooks
// module imports these types; `claude plugin validate` holds every `$.state`
// key the module names to this file. Self-contained: no import, no reference.

/** The four band members a piece of work can be assigned to. */
export type KessokuMember = 'bocchi' | 'nijika' | 'ryo' | 'kita'

/** The expression a member's face shows. */
export type KessokuMood = 'anxious' | 'focused' | 'happy' | 'panic' | 'melting' | 'hiding'

/**
 * What a subagent's slime shows: `active` while the act runs (a bounce),
 * `idle` while it is pending or waiting (a breath), `asleep` once it is done,
 * failed or killed (a doze, a z drifting up). Derived from the agent's status.
 */
export type KessokuSlimeState = 'active' | 'idle' | 'asleep'

/** Token counts, summed over every response of one agent loop. */
export type KessokuUsage = {
  input: number
  output: number
  cacheRead: number
  cacheWrite: number
}

/** The main loop (`id: 'main'`) or one subagent, as the band panel shows it. */
export type KessokuAgent = {
  id: string
  member: KessokuMember
  description: string
  type: string
  status: 'pending' | 'running' | 'waiting' | 'idle' | 'completed' | 'failed' | 'killed'
  task: string
  startedAt: number
  endedAt: number | null
  model: string
  usage: KessokuUsage
  context: number
  steps: number
  tools: number
  cost: number
  isError: boolean
  /** Calls by tool name, this act (the main loop's reset at every turn). */
  toolTally: Record<string, number>
  /** The task line's words for its newest call; empty before one. */
  lastTool: string
}

/** What the Kessoku Band panel and the strip above the prompt draw from. */
export type KessokuBand = {
  agents: KessokuAgent[]
  mood: KessokuMood
  mainTask: string
  contextPercent: number
  window: number
  sessionUsd: number
  /** The fullest rate-limit window of the plan, in percent; 0 off a subscription. */
  rateLimitPercent: number
  isWorking: boolean
  lastError: string
  /** The set: the main loop's turn, counted from the session's first (0 before it). */
  set: number
  /** What the set was asked: the head of the prompt that started it (mainTask follows the tool in hand). */
  setPrompt: string
  /** When the current (or last) set started. */
  setStartedAt: number
}

/** Cache Tax: when the prompt cache was last warmed, and what a cold send costs. */
export type KessokuCache = {
  lastWarmAt: number
  contextTokens: number
  model: string
  keepWarmUntil: number
  isArmed: boolean
  heldAt: number
  /** The prompt that was held, so a timely re-send (and only that) passes without a second warning. */
  heldText: string
  heldUsd: number
  warmUsd: number
  pings: number
  pingUsd: number
  /** Pings that found the cache already cold and paid to re-write it. */
  misses: number
  lastPingNote: string
  /** The engine's own re-cache estimate from the last model switch, and the model it priced. */
  engineWriteUsd: number
  engineModel: string
}

/** Blast Radius: the risky command on hold and what it would do. */
export type KessokuBlast = {
  command: string
  label: string
  summary: string
  lines: string[]
  more: number
  note: string
  where: 'pane' | 'band'
  isHeld: boolean
}

/** One file lit on the file tree: being edited, edited, read, or committed. */
export type KessokuLight = {
  path: string
  kind: 'editing' | 'edited' | 'read' | 'committed'
  at: number
  by: KessokuMember
}

/** The file tree pane: the project's paths and the lights on them. */
export type KessokuTree = {
  root: string
  paths: string[]
  lights: KessokuLight[]
  isOpen: boolean
  isBand: boolean
  builtAt: number
}

/** Reflect: the band-manager memo Nijika drafts from a correction, or holds for a rule Claude proposed through the memo tool. */
export type KessokuMemo = {
  rule: string
  /** The correction it was drafted from, or the proposal's own why. */
  original: string
  at: number
  status: 'drafting' | 'open' | 'editing' | 'saved' | 'skipped'
  savedTo: string
  /** Who proposed the rule through the memo tool (Bocchi for the main loop); absent on a memo drafted from a correction. */
  by?: KessokuMember
}

/** A rule proposed through the memo tool while another memo was up, waiting its turn on Nijika's card. */
export type KessokuProposal = {
  rule: string
  why: string
  by: KessokuMember
  at: number
}

/** One track of the Replay Theater setlist: one file edit as a unified diff. */
export type KessokuTrack = {
  tool: string
  file: string
  hunks: string
  add: number
  del: number
  note: string
  by: KessokuMember
}

/** Replay Theater: the last turn's setlist and where the viewer stands. */
export type KessokuReplay = {
  tracks: KessokuTrack[]
  index: number
  isOpen: boolean
  inBand: boolean
  setlist: number
}

/** Which of the theme's drawings are up. */
export type KessokuUi = {
  isPanelOpen: boolean
  isStripHidden: boolean
  panelWhere: 'pane' | 'band' | 'none'
  /** The member whose channel is open across the mixer; null for the mix. */
  solo: KessokuMember | null
  /** The act listed first on her solo (pressed under her pit); null for the newest. */
  soloAct: string | null
  /** When an automatic solo (or one whose last act ended) returns to the mix; 0 for a chosen one with acts on stage. */
  soloUntil: number
  /** The solo was chosen (her name pressed, /bocchi solo), not opened by autoSolo: her new act calls off its pending end, and autoSolo never replaces it. */
  soloChosen: boolean
}

declare module 'claude-code' {
  interface PluginState {
    'kessoku-ultimate-bocchi': {
      band: KessokuBand
      cache: KessokuCache
      blast: KessokuBlast | null
      tree: KessokuTree
      /** The shimmer's beat while a file is being edited: its own value, so only the tree pane redraws with it. */
      frame: number
      memo: KessokuMemo | null
      /** Proposed rules queued behind the memo on screen, oldest first. */
      proposals: KessokuProposal[]
      replay: KessokuReplay
      ui: KessokuUi
    }
  }
}
